import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./AdminPage.css";

function AdminPage() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState("dashboard");

  const [faqs, setFaqs] = useState([]);
  const [replyText, setReplyText] = useState({});

  useEffect(() => {
    fetchFaqs();
  }, []);

  const fetchFaqs = () => {
    fetch("http://localhost:8081/faqs")
      .then((res) => res.json())
      .then((data) => setFaqs(data))
      .catch((err) => console.error("Error fetching FAQs:", err));
  };

  const handleReply = (faqId) => {
    const reply = replyText[faqId];
    if (!reply) return;

    fetch(`http://localhost:8081/faqs/${faqId}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ answer: reply }),
    })
      .then((res) => res.json())
      .then(() => {
        fetchFaqs();
        setReplyText({ ...replyText, [faqId]: "" });
      })
      .catch((err) => console.error("Error posting reply:", err));
  };

  const renderContent = () => {
    if (activeTab === "faq") {
      return (
        <div>
          <h2>User FAQs</h2>
          {faqs.length === 0 ? (
            <p>No FAQs submitted yet.</p>
          ) : (
            <ul>
              {faqs.map((faq) => (
                <li key={faq.id}>
                  <strong>Q:</strong> {faq.question} <br />
                  <strong>A:</strong> {faq.answer || "No reply yet"}
                  <div>
                    <textarea
                      value={replyText[faq.id] || ""}
                      onChange={(e) =>
                        setReplyText({ ...replyText, [faq.id]: e.target.value })
                      }
                      placeholder="Type your reply..."
                    />
                    <button onClick={() => handleReply(faq.id)}>Send Reply</button>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </div>
      );
    }

    // keep your existing dashboard/bookings/facilities/analytics rendering here
  };

  return (
    <div className="admin-dashboard">
      <div className="sidebar">
        <h2>Admin Panel</h2>
        <ul>
          <li onClick={() => setActiveTab("dashboard")}>Dashboard</li>
          <li onClick={() => setActiveTab("bookings")}>View Bookings</li>
          <li onClick={() => setActiveTab("facilities")}>Facilities</li>
          <li onClick={() => setActiveTab("analytics")}>Facility Analytics</li>
          <li onClick={() => setActiveTab("faq")}>FAQs</li>
        </ul>
      </div>

      <div className="main-content">
        <div className="topbar">
          <h1>{activeTab.charAt(0).toUpperCase() + activeTab.slice(1)}</h1>
          <button onClick={() => { localStorage.clear(); navigate("/admin-login"); }}>Logout</button>
        </div>
        <div className="content-area">{renderContent()}</div>
      </div>
    </div>
  );
}

export default AdminPage;
